import { useEffect, useMemo, useState } from 'react'

type Business = 'all' | 'lapas' | 'mercadinho'
type Page = 'inicio' | 'vendas' | 'pedidos' | 'estoque' | 'compras' | 'caixa' | 'fiado' | 'resultados' | 'inteligencia' | 'sorteios' | 'config'
type Product = { id:number; business:'lapas'|'mercadinho'; name:string; type:string; size:string; category:string; unit:string; temperature?:'Gelada'|'Natural'|''; cost:number; price:number; stock:number; minStock:number; active:boolean; description?:string; image?:string }
type Sale = { id:number; business:'lapas'|'mercadinho'; productId:number; productName:string; quantity:number; total:number; payment:'PIX'|'Dinheiro'|'Cartão'|'Fiado'; date:string; customerId?:number; creditFeePercent?:number; creditFee?:number }
type Purchase = { id:number; business:'lapas'|'mercadinho'; productId:number; productName:string; quantity:number; total:number; supplier:string; date:string }
type Customer = { id:number; name:string; phone:string; address:string; reference:string; balance:number }
type ClientRequest = { id:number; name:string; customer:string; date:string; status:'pendente'|'avaliar'|'não trabalhar' }
type DeliveryConfig = {enabled:boolean;freeEnabled:boolean;freeAbove:number;regions:{name:string;fee:number}[];defaultFee:number;minOrder:number}
type PaymentConfig = {pixKey:string;cardLink:string;cardProvider:string}
type OrderStatus = 'aguardando_pagamento'|'pago_preparo'|'saiu_entrega'|'pronto_retirada'|'entregue'
type Order = {id:number;business:'lapas'|'mercadinho';items:{productId:number;name:string;quantity:number;unitPrice:number;removed?:string[];additions?:{name:string;price:number}[];note?:string}[];subtotal:number;fee:number;total:number;payment:'PIX'|'Cartão';customer:{name:string;phone:string;address:string;reference:string};delivery:'entrega'|'retirada';region:string;status:OrderStatus;createdAt:string}
