const initialSales:Sale[] = [
{id:1,business:'lapas',productId:1,productName:'X-Burger',quantity:3,total:54,payment:'PIX',date:new Date().toISOString()},
{id:2,business:'lapas',productId:3,productName:'X-Bacon',quantity:2,total:46,payment:'Dinheiro',date:new Date().toISOString()},
{id:3,business:'mercadinho',productId:101,productName:'Arroz Branco',quantity:1,total:31,payment:'PIX',date:new Date().toISOString()}
]
const money=(v:number)=>v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
const today=()=>new Date().toLocaleDateString('pt-BR')
const dateBR=(value:string)=>new Date(value).toLocaleDateString('pt-BR')
const save=<T,>(key:string,value:T)=>localStorage.setItem(key,JSON.stringify(value))
const load=<T,>(key:string,fallback:T):T=>{try{return JSON.parse(localStorage.getItem(key)||'null')??fallback}catch{return fallback}}

function App(){
const[page,setPage]=useState<Page>('inicio'),[business,setBusiness]=useState<Business>('all')
const[products,setProducts]=useState<Product[]>(()=>{const saved=load<Product[]>('mn-products',initialProducts);const savedById=new Map(saved.map(p=>[p.id,p]));const merged=initialProducts.map(def=>({...def,...savedById.get(def.id)}));const extras=saved.filter(p=>!initialProducts.some(d=>d.id===p.id));return [...merged,...extras].map(p=>{const defaults=initialProducts.find(x=>x.id===p.id);return {...p,type:p.type||p.category||'',size:p.size||p.unit||'',temperature:p.temperature||'',active:p.price>0 ? p.active!==false : false,description:p.description||defaults?.description||''}})})
const[sales,setSales]=useState<Sale[]>(()=>load('mn-sales',initialSales))
const[purchases,setPurchases]=useState<Purchase[]>(()=>load('mn-purchases',[]))
const[customers,setCustomers]=useState<Customer[]>(()=>load('mn-customers',[]))
const[requests,setRequests]=useState<ClientRequest[]>(()=>load('mn-requests',[]))
const[places,setPlaces]=useState<string[]>(()=>load('mn-places',['Atacadão','Assaí','Mercado do bairro']))
const[creditFeeEnabled,setCreditFeeEnabled]=useState<boolean>(()=>load('mn-credit-fee-enabled',false))
const[creditFeePercent,setCreditFeePercent]=useState<number>(()=>load('mn-credit-fee-percent',0))
const[delivery,setDelivery]=useState<Record<'lapas'|'mercadinho',DeliveryConfig>>(()=>load('mn-delivery',defaultDelivery))
const[paymentConfig,setPaymentConfig]=useState<Record<'lapas'|'mercadinho',PaymentConfig>>(()=>load('mn-payment-config',{lapas:{pixKey:'21968395478',cardLink:'',cardProvider:'PagBank'},mercadinho:{pixKey:'14442008795',cardLink:'',cardProvider:'PagBank'}}))
const[orders,setOrders]=useState<Order[]>(()=>load('mn-orders',[]))
const[toast,setToast]=useState(''),[search,setSearch]=useState('')
useEffect(()=>save('mn-products',products),[products]);useEffect(()=>save('mn-sales',sales),[sales]);useEffect(()=>save('mn-purchases',purchases),[purchases]);useEffect(()=>save('mn-customers',customers),[customers]);useEffect(()=>save('mn-requests',requests),[requests]);useEffect(()=>save('mn-places',places),[places]);useEffect(()=>save('mn-credit-fee-enabled',creditFeeEnabled),[creditFeeEnabled]);useEffect(()=>save('mn-credit-fee-percent',creditFeePercent),[creditFeePercent]);useEffect(()=>save('mn-delivery',delivery),[delivery]);useEffect(()=>save('mn-payment-config',paymentConfig),[paymentConfig]);useEffect(()=>save('mn-orders',orders),[orders])
const visibleProducts=products.filter(p=>p.active&&(business==='all'||p.business===business))
const visibleSales=sales.filter(s=>business==='all'||s.business===business),visiblePurchases=purchases.filter(p=>business==='all'||p.business===business)
const revenue=visibleSales.reduce((a,s)=>a+s.total,0),purchaseTotal=visiblePurchases.reduce((a,p)=>a+p.total,0),lowStock=visibleProducts.filter(p=>p.stock<=p.minStock),openFiado=customers.reduce((a,c)=>a+c.balance,0)
const estimatedGross=visibleSales.reduce((sum,sale)=>{const p=products.find(x=>x.id===sale.productId);return sum+sale.quantity*((p?.price||0)-(p?.cost||0))},0)
const notify=(m:string)=>{setToast(m);window.setTimeout(()=>setToast(''),2800)}
const cleanPath=window.location.pathname.replace(/\/+$/,'')||'/'; const appPath=cleanPath.startsWith('/capacitamixthais-beep')?cleanPath.replace('/capacitamixthais-beep','')||'/':cleanPath; const legacyStore=new URLSearchParams(window.location.search).get('loja'); const publicStore=(appPath==='/lapasburguer'?'lapas':appPath==='/mercadodafamilia'?'mercadinho':legacyStore) as 'lapas'|'mercadinho'|null
const sell=(productId:number,quantity:number,payment:Sale['payment'],customerId?:number)=>{const p=products.find(x=>x.id===productId);if(!p||quantity<=0)return;if(p.stock<quantity)return notify('Estoque insuficiente para essa venda.');if(payment==='Fiado'&&!customerId)return notify('Selecione o cliente do fiado.');const base=p.price*quantity;const fee=payment==='Fiado'&&creditFeeEnabled&&creditFeePercent>0?Number((base*creditFeePercent/100).toFixed(2)):0;const total=Number((base+fee).toFixed(2));setSales(v=>[{id:Date.now(),business:p.business,productId:p.id,productName:p.name,quantity,total,payment,customerId,creditFeePercent:fee?creditFeePercent:0,creditFee:fee,date:new Date().toISOString()},...v]);if(payment==='Fiado'&&customerId)setCustomers(v=>v.map(c=>c.id===customerId?{...c,balance:Number((c.balance+total).toFixed(2))}:c));setProducts(v=>v.map(x=>x.id===p.id?{...x,stock:x.stock-quantity}:x));notify(fee?'Fiado registrado com acréscimo aplicado.':'Venda registrada e estoque atualizado.')}
const addPurchase=(productId:number,quantity:number,supplier:string)=>{const p=products.find(x=>x.id===productId);if(!p||quantity<=0)return;setPurchases(v=>[{id:Date.now(),business:p.business,productId:p.id,productName:p.name,quantity,total:p.cost*quantity,supplier:supplier||'Fornecedor não informado',date:new Date().toISOString()},...v]);setProducts(v=>v.map(x=>x.id===p.id?{...x,stock:x.stock+quantity}:x));notify('Compra registrada e estoque atualizado.')}
const createWhatsApp=()=>{const list=products.filter(p=>p.business==='mercadinho'&&p.active&&p.stock>0).slice(0,30).map(p=>'• '+p.name+' — '+money(p.price)).join('%0A');const text='Olá! Quero fazer um pedido no Mercadinho da Família.%0A%0A'+list+'%0A%0AQuero saber a disponibilidade dos produtos e combinar a entrega/retirada.';window.open('https://wa.me/?text='+text,'_blank')}
const resetDemo=()=>{setProducts(initialProducts);setSales(initialSales);setPurchases([]);setCustomers([{id:1,name:'Cliente exemplo',phone:'',address:'',reference:'',balance:35}]);notify('Dados de demonstração restaurados.')}
if(publicStore){return <PublicStore business={publicStore} products={products} delivery={delivery[publicStore]} payment={paymentConfig[publicStore]} orders={orders} setOrders={setOrders} />}
return <div className="app">
<header className="topbar"><div className="brand" onClick={()=>{setPage('inicio');setBusiness('all')}}><div className="brand-mark">MN</div><div><strong>Meu Negócio</strong><span>gestão simples, sem complicação</span></div></div><div className="top-actions"><span className="date-chip">Hoje, {today()}</span><select value={business} onChange={e=>setBusiness(e.target.value as Business)}><option value="all">Visão geral</option><option value="lapas">🍔 Lapas Burguer</option><option value="mercadinho">🛒 Mercadinho da Família</option></select></div></header>
<div className="layout"><aside className="sidebar">
<button className={page==='inicio'?'nav active':'nav'} onClick={()=>setPage('inicio')}>⌂ <span>Início</span></button><div className="nav-label">Operação</div>
<button className={page==='vendas'?'nav active':'nav'} onClick={()=>setPage('vendas')}>🧾 <span>Vendas</span></button><button className={page==='pedidos'?'nav active':'nav'} onClick={()=>setPage('pedidos')}>🛵 <span>Pedidos</span>{orders.filter(o=>o.status==='pago_preparo').length>0&&<b className="badge">{orders.filter(o=>o.status==='pago_preparo').length}</b>}</button>
<button className={page==='estoque'?'nav active':'nav'} onClick={()=>setPage('estoque')}>📦 <span>Estoque</span>{lowStock.length>0&&<b className="badge">{lowStock.length}</b>}</button>
<button className={page==='compras'?'nav active':'nav'} onClick={()=>setPage('compras')}>🚚 <span>Compras</span></button>
<button className={page==='caixa'?'nav active':'nav'} onClick={()=>setPage('caixa')}>💰 <span>Caixa</span></button>
<button className={page==='fiado'?'nav active':'nav'} onClick={()=>setPage('fiado')}>👤 <span>Fiado</span>{openFiado>0&&<b className="badge warn">!</b>}</button>
<div className="nav-label">Acompanhar</div><button className={page==='resultados'?'nav active':'nav'} onClick={()=>setPage('resultados')}>📊 <span>Meu resultado</span></button><button className={page==='sorteios'?'nav active':'nav'} onClick={()=>setPage('sorteios')}>🎁 <span>Sorteios</span></button><button className={page==='inteligencia'?'nav active':'nav'} onClick={()=>setPage('inteligencia')}>🧠 <span>Inteligência</span></button><button className={page==='config'?'nav active':'nav'} onClick={()=>setPage('config')}>⚙️ <span>Configurações</span></button>
<div className="sidebar-help"><strong>Precisa de ajuda?</strong><span>O sistema foi feito para você não precisar entender de contabilidade para saber como o negócio está.</span></div>
</aside><main className="main">
{page==='inicio'&&<Dashboard business={business} revenue={revenue} estimatedGross={estimatedGross} purchaseTotal={purchaseTotal} lowStock={lowStock} sales={visibleSales} products={visibleProducts} setPage={setPage} setBusiness={setBusiness} createWhatsApp={createWhatsApp}/>}
{page==='vendas'&&<SalesPage products={visibleProducts} business={business} onSell={sell} search={search} setSearch={setSearch} sales={visibleSales} customers={customers} creditFeeEnabled={creditFeeEnabled} creditFeePercent={creditFeePercent}/>}
{page==='pedidos'&&<OrdersPage orders={orders} setOrders={setOrders}/>}{page==='estoque'&&<StockPage products={visibleProducts} search={search} setSearch={setSearch} onAdjust={(id,d)=>setProducts(v=>v.map(p=>p.id===id?{...p,stock:Math.max(0,p.stock+d)}:p))} onSaveProduct={(p)=>{setProducts(v=>v.some(x=>x.id===p.id)?v.map(x=>x.id===p.id?p:x):[...v,p]);notify(p.id?'Produto atualizado.':'Produto cadastrado.')}}/>}
{page==='compras'&&<PurchasesPage products={visibleProducts} purchases={visiblePurchases} onPurchase={addPurchase}/>}
{page==='caixa'&&<CashPage sales={visibleSales} purchases={visiblePurchases}/>}
{page==='fiado'&&<CreditPage customers={customers} setCustomers={setCustomers}/>}
{page==='resultados'&&<ResultsPage products={visibleProducts} sales={visibleSales} purchases={visiblePurchases}/>}\n{page==='sorteios'&&<SorteiosPage customers={customers} products={products}/>}
{page==='inteligencia'&&<IntelligencePage products={visibleProducts} sales={visibleSales} purchases={visiblePurchases} customers={customers} setCustomers={setCustomers} requests={requests} setRequests={setRequests} places={places} setPlaces={setPlaces} setProducts={setProducts}/>}
{page==='config'&&<SettingsPage onReset={resetDemo} createWhatsApp={createWhatsApp} creditFeeEnabled={creditFeeEnabled} creditFeePercent={creditFeePercent} setCreditFeeEnabled={setCreditFeeEnabled} setCreditFeePercent={setCreditFeePercent} delivery={delivery} setDelivery={setDelivery} paymentConfig={paymentConfig} setPaymentConfig={setPaymentConfig}/>}
</main></div>{toast&&<div className="toast">✓ {toast}</div>}</div>
}

function Dashboard({business,revenue,estimatedGross,purchaseTotal,lowStock,sales,products,setPage,setBusiness,createWhatsApp}:{business:Business;revenue:number;estimatedGross:number;purchaseTotal:number;lowStock:Product[];sales:Sale[];products:Product[];setPage:(p:Page)=>void;setBusiness:(b:Business)=>void;createWhatsApp:()=>void}){
const title=business==='lapas'?'Lapas Burguer':business==='mercadinho'?'Mercadinho da Família':'Visão geral'
return <div><div className="page-head"><div><span className="eyebrow">PAINEL DE HOJE</span><h1>{title}</h1><p>Veja rapidamente o que entrou, o que saiu e o que precisa da sua atenção.</p></div><div className="head-buttons"><button className="secondary" onClick={()=>setPage('vendas')}>+ Registrar venda</button><button className="primary" onClick={()=>setPage('estoque')}>Ver estoque</button></div></div>
{business==='all'&&<div className="business-cards"><button className="business-card lapas" onClick={()=>setBusiness('lapas')}><div className="business-icon">🍔</div><div><strong>LAPAS BURGUER</strong><span>Entrar na gestão dos lanches</span></div><b>→</b></button><button className="business-card market" onClick={()=>setBusiness('mercadinho')}><div className="business-icon">🛒</div><div><strong>MERCADINHO DA FAMÍLIA</strong><span>Entrar na gestão do mercadinho</span></div><b>→</b></button></div>}
<div className="metrics"><Metric label="Vendas registradas" value={money(revenue)} note="total vendido" icon="↗"/><Metric label="Compras" value={money(purchaseTotal)} note="saídas registradas" icon="↓"/><Metric label="Margem bruta estimada" value={money(estimatedGross)} note="antes das despesas" icon="◆"/><Metric label="Estoque baixo" value={String(lowStock.length)} note="itens para conferir" icon="!" danger={lowStock.length>0}/></div>
<div className="grid-2"><section className="card"><div className="card-head"><div><h2>Como está meu negócio?</h2><p>Um resumo sem linguagem complicada.</p></div><button className="link-btn" onClick={()=>setPage('resultados')}>Ver detalhes →</button></div><div className="simple-status"><div><span>💵 Quanto vendi?</span><strong>{money(revenue)}</strong></div><div><span>🚚 Quanto comprei?</span><strong>{money(purchaseTotal)}</strong></div><div><span>📦 O que está acabando?</span><strong>{lowStock.length?lowStock.length+' itens':'Nada urgente'}</strong></div><div><span>💰 O que sobrou das vendas?</span><strong>{money(estimatedGross)}</strong></div></div></section>
<section className="card"><div className="card-head"><div><h2>O que está me dando dinheiro?</h2><p>Custo, preço e diferença por produto.</p></div></div><div className="mini-list">{products.slice(0,5).map(p=><div className="mini-row" key={p.id}><span>{p.name}</span><strong>{money(p.price-p.cost)}</strong><small>por unidade</small></div>)}</div></section></div>
<div className="grid-2"><section className="card"><div className="card-head"><div><h2>Últimas vendas</h2><p>As movimentações mais recentes.</p></div><button className="link-btn" onClick={()=>setPage('vendas')}>Ver todas →</button></div><Table rows={sales.slice(0,6)}/></section>
<section className="card"><div className="card-head"><div><h2>Precisa comprar</h2><p>Itens abaixo do estoque mínimo.</p></div><button className="link-btn" onClick={()=>setPage('compras')}>Lista de compras →</button></div>{lowStock.length?<div className="alert-list">{lowStock.map(p=><div key={p.id}><span>⚠️ {p.name}</span><b>{p.stock} {p.unit}</b><small>mínimo {p.minStock}</small></div>)}</div>:<div className="empty">✓ Nenhum item abaixo do mínimo.</div>}</section></div>
{business!=='lapas'&&<section className="whatsapp-banner"><div><strong>📲 Pedidos pelo WhatsApp</strong><span>O Mercadinho pode enviar uma lista de produtos para o cliente iniciar o pedido.</span></div><button onClick={createWhatsApp}>Abrir pedido no WhatsApp</button></section>}</div>
}
function Metric({label,value,note,icon,danger}:{label:string;value:string;note:string;icon:string;danger?:boolean}){return <div className="metric"><div className={danger?'metric-icon danger':'metric-icon'}>{icon}</div><div><span>{label}</span><strong>{value}</strong><small>{note}</small></div></div>}

function SalesPage({products,onSell,search,setSearch,sales,customers,creditFeeEnabled,creditFeePercent}:{products:Product[];business:Business;onSell:(id:number,q:number,p:Sale['payment'],customerId?:number)=>void;search:string;setSearch:(s:string)=>void;sales:Sale[];customers:Customer[];creditFeeEnabled:boolean;creditFeePercent:number}){
const[selected,setSelected]=useState(products[0]?.id||0),[qty,setQty]=useState(1),[payment,setPayment]=useState<Sale['payment']>('PIX'),[customerId,setCustomerId]=useState<number|undefined>(undefined)
const filtered=products.filter(p=>p.name.toLowerCase().includes(search.toLowerCase()))
useEffect(()=>{if(!filtered.some(p=>p.id===selected))setSelected(filtered[0]?.id||0)},[search])
const p=products.find(x=>x.id===selected)
return <div><div className="page-head"><div><span className="eyebrow">OPERAÇÃO</span><h1>Vendas</h1><p>Registre uma venda em poucos toques. O estoque é atualizado automaticamente.</p></div></div><div className="sale-layout"><section className="card sale-form"><h2>Registrar venda</h2><label>Produto<input placeholder="Buscar produto..." value={search} onChange={e=>setSearch(e.target.value)}/></label><div className="product-picker">{filtered.slice(0,8).map(x=><button className={selected===x.id?'selected':''} key={x.id} onClick={()=>setSelected(x.id)}><span>{x.business==='lapas'?'🍔':'🛒'}</span><div><strong>{x.name}</strong><small>{money(x.price)} · estoque {x.stock}</small></div></button>)}</div><div className="form-grid"><label>Quantidade<input type="number" min="1" max={p?.stock||1} value={qty} onChange={e=>setQty(Number(e.target.value))}/></label><label>Pagamento<select value={payment} onChange={e=>setPayment(e.target.value as Sale['payment'])}><option>PIX</option><option>Dinheiro</option><option>Cartão</option><option>Fiado</option></select></label>{payment==='Fiado'&&<label>Cliente<select value={customerId??''} onChange={e=>setCustomerId(e.target.value?Number(e.target.value):undefined)}><option value="">Selecione o cliente</option>{customers.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>}</div><div className="total-box"><span>Total da venda</span><strong>{money((p?.price||0)*qty+(payment==='Fiado'&&creditFeeEnabled?((p?.price||0)*qty*creditFeePercent/100):0))}</strong>{payment==='Fiado'&&creditFeeEnabled&&creditFeePercent>0&&<small>Acréscimo do fiado: {creditFeePercent}%</small>}</div><button className="primary full" onClick={()=>{if(p){onSell(p.id,qty,payment,customerId);setQty(1)}}}>✓ Registrar venda</button></section><section className="card"><div className="card-head"><div><h2>Vendas recentes</h2><p>As movimentações registradas.</p></div></div><Table rows={sales.slice(0,15)}/></section></div></div>
}
function Table({rows}:{rows:Sale[]}){if(!rows.length)return <div className="empty">Nenhuma venda registrada ainda.</div>;return <div className="table-wrap"><table><thead><tr><th>Produto</th><th>Qtd.</th><th>Pagamento</th><th>Total</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{r.productName}</td><td>{r.quantity}</td><td><span className="pill">{r.payment}</span></td><td><strong>{money(r.total)}</strong></td></tr>)}</tbody></table></div>}

function StockPage({products,search,setSearch,onAdjust,onSaveProduct}:{products:Product[];search:string;setSearch:(s:string)=>void;onAdjust:(id:number,d:number)=>void;onSaveProduct:(p:Product)=>void}){
const [editing,setEditing]=useState<Product|null>(null),[open,setOpen]=useState(false);
const filtered=products.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())||p.type.toLowerCase().includes(search.toLowerCase())||p.size.toLowerCase().includes(search.toLowerCase())||p.category.toLowerCase().includes(search.toLowerCase()));
const blank:Product={id:0,business:products[0]?.business||'mercadinho',name:'',type:'',size:'',category:'',unit:'un',temperature:'',cost:0,price:0,stock:0,minStock:1,active:true};
return <div><div className="page-head"><div><span className="eyebrow">OPERAÇÃO</span><h1>Estoque</h1><p>Controle o estoque em tabela. Cada produto pode ter tipo, tamanho/apresentação e, quando necessário, temperatura.</p></div><button className="primary" onClick={()=>{setEditing({...blank,id:Date.now()});setOpen(true)}}>+ Adicionar produto</button></div>
<div className="toolbar"><input placeholder="🔎 Procurar nome, tipo, tamanho ou categoria..." value={search} onChange={e=>setSearch(e.target.value)}/><span>{filtered.length} produtos</span></div>
<section className="card table-card"><div className="table-wrap"><table><thead><tr><th>Nome</th><th>Tipo</th><th>Tamanho</th><th>Quantidade</th><th>Estoque mínimo</th><th>Preço</th><th>Disponível</th><th></th></tr></thead><tbody>{filtered.map(p=><tr key={p.id}><td><strong>{p.name}</strong><small>{p.business==='lapas'?'🍔 Lapas Burguer':'🛒 Mercadinho'}{p.temperature?' · '+p.temperature:''}</small></td><td>{p.type||p.category||'—'}</td><td>{p.size||p.unit||'—'}</td><td><button className="tiny" onClick={()=>onAdjust(p.id,-1)}>−</button><strong style={{margin:'0 8px'}}>{p.stock}</strong><button className="tiny" onClick={()=>onAdjust(p.id,1)}>+</button> {p.unit}</td><td>{p.minStock}</td><td>{money(p.price)}</td><td>{p.active?<span className="status ok">Sim</span>:<span className="status danger">Não</span>}</td><td><button className="tiny" onClick={()=>{setEditing(p);setOpen(true)}}>Editar</button></td></tr>)}</tbody></table></div></section>
{open&&editing&&<ProductEditor product={editing} onClose={()=>setOpen(false)} onSave={p=>{onSaveProduct(p);setOpen(false)}}/>}</div>}
function ProductEditor({product,onClose,onSave}:{product:Product;onClose:()=>void;onSave:(p:Product)=>void}){
const [p,setP]=useState<Product>({...product,type:product.type||product.category||'',size:product.size||product.unit||'',temperature:product.temperature||''});
const set=(k:keyof Product,v:any)=>setP(x=>({...x,[k]:v}));
return <div className="modal-backdrop"><div className="modal"><div className="card-head"><div><h2>{product.id?'Editar produto':'Adicionar produto'}</h2><p>Os campos mudam conforme o produto. Temperatura só aparece quando aplicável.</p></div><button className="tiny" onClick={onClose}>✕</button></div>
<div className="form-grid"><label>Negócio<select value={p.business} onChange={e=>set('business',e.target.value)}><option value="lapas">🍔 Lapas Burguer</option><option value="mercadinho">🛒 Mercadinho da Família</option></select></label><label>Tipo<input value={p.type} onChange={e=>set('type',e.target.value)} placeholder="Ex.: Cesta Básica, Bebida, Limpeza"/></label><label className="span-2">Nome do produto<input autoFocus value={p.name} onChange={e=>set('name',e.target.value)}/></label><label>Tamanho / apresentação<input value={p.size} onChange={e=>set('size',e.target.value)} placeholder="Ex.: 1 kg, 500 g, 2 L, caixa"/></label><label>Unidade de controle<input value={p.unit} onChange={e=>set('unit',e.target.value)} placeholder="un, pct, cx..."/></label><label>Temperatura<select value={p.temperature||''} onChange={e=>set('temperature',e.target.value as Product['temperature'])}><option value="">Não se aplica</option><option value="Gelada">Gelada</option><option value="Natural">Natural</option></select></label><label>Categoria<input value={p.category} onChange={e=>set('category',e.target.value)}/></label><label>Custo<input type="number" step="0.01" value={p.cost} onChange={e=>set('cost',Number(e.target.value)||0)}/></label><label>Preço de venda<input type="number" step="0.01" value={p.price} onChange={e=>set('price',Number(e.target.value)||0)}/></label><label>Quantidade em estoque<input type="number" min="0" value={p.stock} onChange={e=>set('stock',Number(e.target.value)||0)}/></label><label>Estoque mínimo<input type="number" min="0" value={p.minStock} onChange={e=>set('minStock',Number(e.target.value)||0)}/></label></div>
<label className="span-2">Descrição do produto<textarea value={p.description||''} onChange={e=>set('description',e.target.value)} placeholder="Ex.: pão, hambúrguer artesanal, queijo, salada e molho especial." rows={4}/></label>
<label style={{display:'flex',gap:8,alignItems:'center',marginTop:12}}><input type="checkbox" checked={p.active} disabled={p.price<=0} onChange={e=>set('active',e.target.checked)}/> Disponível para venda {p.price<=0&&<small> (cadastre um preço para ativar)</small>}</label>
<div className="modal-actions"><button className="secondary" onClick={onClose}>Cancelar</button><button className="primary" disabled={!p.name.trim()||p.price<=0} onClick={()=>onSave(p)}>Salvar produto</button></div></div></div>}

function PurchasesPage({products,purchases,onPurchase}:{products:Product[];purchases:Purchase[];onPurchase:(id:number,q:number,s:string)=>void}){const[id,setId]=useState(products[0]?.id||0),[qty,setQty]=useState(1),[supplier,setSupplier]=useState('');return <div><div className="page-head"><div><span className="eyebrow">REPOSIÇÃO</span><h1>Compras</h1><p>Registre o que comprou. O sistema soma ao estoque e mostra a saída de dinheiro.</p></div></div><div className="grid-2"><section className="card"><h2>Registrar compra</h2><label>Produto<select value={id} onChange={e=>setId(Number(e.target.value))}>{products.map(p=><option key={p.id} value={p.id}>{p.name} — custo {money(p.cost)}</option>)}</select></label><div className="form-grid"><label>Quantidade<input type="number" min="1" value={qty} onChange={e=>setQty(Number(e.target.value))}/></label><label>Fornecedor<input placeholder="Nome do fornecedor" value={supplier} onChange={e=>setSupplier(e.target.value)}/></label></div><div className="total-box"><span>Saída registrada</span><strong>{money((products.find(p=>p.id===id)?.cost||0)*qty)}</strong></div><button className="primary full" onClick={()=>{onPurchase(id,qty,supplier);setQty(1);setSupplier('')}}>✓ Registrar compra</button></section><section className="card"><div className="card-head"><div><h2>Lista de compras</h2><p>Itens abaixo do estoque mínimo.</p></div></div><div className="alert-list">{products.filter(p=>p.stock<=p.minStock).map(p=><div key={p.id}><span>⚠️ {p.name}</span><b>comprar {Math.max(1,p.minStock*2-p.stock)}</b><small>estoque atual: {p.stock}</small></div>)}</div></section></div><section className="card"><div className="card-head"><h2>Compras registradas</h2></div><div className="table-wrap"><table><thead><tr><th>Produto</th><th>Qtd.</th><th>Fornecedor</th><th>Total</th></tr></thead><tbody>{purchases.slice(0,15).map(p=><tr key={p.id}><td>{p.productName}</td><td>{p.quantity}</td><td>{p.supplier}</td><td>{money(p.total)}</td></tr>)}</tbody></table></div></section></div>}

function CashPage({sales,purchases}:{sales:Sale[];purchases:Purchase[]}){const payments=['PIX','Dinheiro','Cartão','Fiado'] as const;const inBy=payments.map(x=>({x,total:sales.filter(s=>s.payment===x).reduce((a,s)=>a+s.total,0)}));const totalIn=sales.reduce((a,s)=>a+s.total,0),totalOut=purchases.reduce((a,s)=>a+s.total,0);return <div><div className="page-head"><div><span className="eyebrow">DINHEIRO</span><h1>Caixa</h1><p>Veja quanto entrou, quanto saiu e o saldo das movimentações registradas.</p></div></div><div className="metrics"><Metric label="Entradas" value={money(totalIn)} note="vendas" icon="↗"/><Metric label="Saídas" value={money(totalOut)} note="compras registradas" icon="↓"/><Metric label="Saldo das movimentações" value={money(totalIn-totalOut)} note="antes de outras despesas" icon="="/></div><section className="card"><h2>Entradas por forma de pagamento</h2><div className="cash-list">{inBy.map(x=><div key={x.x}><span>{x.x}</span><strong>{money(x.total)}</strong><div className="bar"><i style={{width:totalIn?Math.min(100,x.total/totalIn*100)+'%':'0%'}}/></div></div>)}</div></section><div className="info-note">💡 <strong>Importante:</strong> faturamento não é a mesma coisa que lucro. O resultado real precisa considerar compras, despesas, perdas e outros custos.</div></div>}

function CreditPage({customers,setCustomers}:{customers:Customer[];setCustomers:(x:Customer[])=>void}){const[name,setName]=useState(''),[phone,setPhone]=useState('');const add=()=>{if(!name.trim())return;setCustomers([...customers,{id:Date.now(),name:name.trim(),phone,address:'',reference:'',balance:0}]);setName('');setPhone('')};const pay=(id:number)=>setCustomers(customers.map(c=>c.id===id?{...c,balance:0}:c));return <div><div className="page-head"><div><span className="eyebrow">CLIENTES</span><h1>Fiado</h1><p>Controle quem está devendo sem precisar guardar tudo na cabeça.</p></div></div><div className="grid-2"><section className="card"><h2>Novo cliente</h2><label>Nome<input value={name} onChange={e=>setName(e.target.value)} placeholder="Nome do cliente"/></label><label>WhatsApp<input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="(00) 00000-0000"/></label><button className="primary full" onClick={add}>+ Cadastrar cliente</button></section><section className="card"><div className="card-head"><div><h2>Contas em aberto</h2><p>Total: {money(customers.reduce((a,c)=>a+c.balance,0))}</p></div></div><div className="customer-list">{customers.map(c=><div className="customer" key={c.id}><div><strong>{c.name}</strong><small>{c.phone||'Sem telefone'}</small></div><div><b>{money(c.balance)}</b>{c.balance>0&&<button className="tiny pay" onClick={()=>pay(c.id)}>Recebeu</button>}</div></div>)}</div></section></div></div>}

function ResultsPage({products,sales,purchases}:{products:Product[];sales:Sale[];purchases:Purchase[]}){const byProduct=products.map(p=>({p,total:sales.filter(s=>s.productId===p.id).reduce((a,s)=>a+s.quantity,0)})).filter(x=>x.total).sort((a,b)=>b.total-a.total);const revenue=sales.reduce((a,s)=>a+s.total,0),purchasesTotal=purchases.reduce((a,s)=>a+s.total,0);const gross=sales.reduce((a,s)=>a+s.quantity*((products.find(p=>p.id===s.productId)?.price||0)-(products.find(p=>p.id===s.productId)?.cost||0)),0);return <div><div className="page-head"><div><span className="eyebrow">VISÃO DO NEGÓCIO</span><h1>Meu resultado</h1><p>Os números que ajudam a entender se as vendas estão deixando dinheiro no negócio.</p></div></div><div className="result-hero"><div><span>Vendido</span><strong>{money(revenue)}</strong></div><div><span>Compras</span><strong>{money(purchasesTotal)}</strong></div><div><span>Margem bruta estimada</span><strong>{money(gross)}</strong></div></div><div className="grid-2"><section className="card"><h2>O que está me dando dinheiro?</h2><p className="muted">Margem estimada por unidade.</p><div className="profit-list">{products.slice().sort((a,b)=>(b.price-b.cost)-(a.price-a.cost)).slice(0,8).map(p=><div key={p.id}><span>{p.name}</span><b>{money(p.price-p.cost)}</b></div>)}</div></section><section className="card"><h2>Mais vendidos</h2><p className="muted">Quantidade registrada nas vendas.</p><div className="profit-list">{byProduct.slice(0,8).map(x=><div key={x.p.id}><span>{x.p.name}</span><b>{x.total} un.</b></div>)}</div></section></div><div className="info-note">📌 Este painel é uma estimativa de gestão. Para saber o lucro final, registre também despesas como aluguel, energia, taxas de cartão, entregas, salários e perdas.</div></div>}

function SettingsPage({onReset,createWhatsApp,creditFeeEnabled,creditFeePercent,setCreditFeeEnabled,setCreditFeePercent,delivery,setDelivery,paymentConfig,setPaymentConfig}:{onReset:()=>void;createWhatsApp:()=>void;creditFeeEnabled:boolean;creditFeePercent:number;setCreditFeeEnabled:(v:boolean)=>void;setCreditFeePercent:(v:number)=>void;delivery:Record<'lapas'|'mercadinho',DeliveryConfig>;setDelivery:React.Dispatch<React.SetStateAction<Record<'lapas'|'mercadinho',DeliveryConfig>>>;paymentConfig:Record<'lapas'|'mercadinho',PaymentConfig>;setPaymentConfig:React.Dispatch<React.SetStateAction<Record<'lapas'|'mercadinho',PaymentConfig>>>}){const [biz,setBiz]=useState<'lapas'|'mercadinho'>('lapas');const d=delivery[biz];const pay=paymentConfig[biz];const updateD=(patch:Partial<DeliveryConfig>)=>setDelivery(v=>({...v,[biz]:{...v[biz],...patch}}));const addRegion=()=>updateD({regions:[...d.regions,{name:'Nova região',fee:d.defaultFee}]});const updateRegion=(i:number,k:'name'|'fee',v:any)=>updateD({regions:d.regions.map((r,n)=>n===i?{...r,[k]:v}:r)});const removeRegion=(i:number)=>updateD({regions:d.regions.filter((_,n)=>n!==i)});return <div><div className="page-head"><div><span className="eyebrow">SISTEMA</span><h1>Configurações</h1><p>Tudo que influencia o funcionamento pode ser alterado aqui.</p></div></div><div className="grid-2"><section className="card"><h2>Horário do Lapas Burguer</h2><div className="hours"><span>Segunda</span><b>Fechado</b><span>Terça a quinta</span><b>18h às 24h</b><span>Sexta e sábado</span><b>18h às 02h</b><span>Domingo</span><b>18h às 24h</b></div></section><section className="card"><h2>Mercadinho da Família</h2><p className="muted">Catálogo e pedidos online ficam separados da Lapas.</p><button className="secondary full" onClick={createWhatsApp}>📲 Testar pedido pelo WhatsApp</button></section></div><section className="card"><h2>🚚 Entrega — configuração por negócio</h2><div className="toolbar"><select value={biz} onChange={e=>setBiz(e.target.value as 'lapas'|'mercadinho')}><option value="lapas">🍔 Lapas Burguer</option><option value="mercadinho">🛒 Mercadinho da Família</option></select><span>Os valores abaixo são totalmente alteráveis.</span></div><label style={{display:'flex',alignItems:'center',gap:8}}><input type="checkbox" checked={d.enabled} onChange={e=>updateD({enabled:e.target.checked})}/> Aceitar pedidos para entrega</label><div className="form-grid"><label>Pedido mínimo<input type="number" step="0.01" value={d.minOrder} onChange={e=>updateD({minOrder:Number(e.target.value)||0})}/></label><label>Frete padrão<input type="number" step="0.01" value={d.defaultFee} onChange={e=>updateD({defaultFee:Number(e.target.value)||0})}/></label><label style={{display:'flex',alignItems:'center',gap:8}}><input type="checkbox" checked={d.freeEnabled} onChange={e=>updateD({freeEnabled:e.target.checked})}/> Ativar frete grátis</label><label>Frete grátis acima de<input type="number" step="0.01" value={d.freeAbove} onChange={e=>updateD({freeAbove:Number(e.target.value)||0})}/></label></div><h3>Regiões</h3>{d.regions.map((r,i)=><div className="region-row" key={i}><input value={r.name} onChange={e=>updateRegion(i,'name',e.target.value)}/><input type="number" step="0.01" value={r.fee} onChange={e=>updateRegion(i,'fee',Number(e.target.value)||0)}/><button className="tiny" onClick={()=>removeRegion(i)}>✕</button></div>)}<button className="secondary" onClick={addRegion}>+ Adicionar região</button><div className="info-note">💡 O sistema pode usar bairro/região em vez de quilômetros. Se o pedido atingir o valor configurado, o frete passa automaticamente para grátis.</div></section><section className="card"><h2>💳 Pagamento online</h2><p className="muted">PIX e cartão ficam separados por negócio. O cartão será oferecido por <strong>Link de Pagamento PagBank</strong>.</p><div className="form-grid"><label>Chave PIX<input value={pay.pixKey} onChange={e=>setPaymentConfig(v=>({...v,[biz]:{...v[biz],pixKey:e.target.value}}))} placeholder="CPF, CNPJ, telefone, e-mail ou chave aleatória"/></label><label>Provedor do cartão<input value={pay.cardProvider} onChange={e=>setPaymentConfig(v=>({...v,[biz]:{...v[biz],cardProvider:e.target.value}}))} placeholder="Ex.: PagBank"/></label><label style={{gridColumn:'1 / -1'}}>Link de pagamento do cartão<input value={pay.cardLink} onChange={e=>setPaymentConfig(v=>({...v,[biz]:{...v[biz],cardLink:e.target.value}}))} placeholder="Cole aqui o link criado no PagBank"/></label></div><div className="info-note">💡 O link é criado na conta PagBank e depois colado aqui. Assim, o cliente poderá escolher <strong>“Pagar por link”</strong> no catálogo.</div></section><section className="card"><h2>💳 Ajuste opcional para fiado</h2><p className="muted">Só aplica quando ativado e somente em vendas fiadas.</p><label style={{display:'flex',alignItems:'center',gap:10}}><input type="checkbox" checked={creditFeeEnabled} onChange={e=>setCreditFeeEnabled(e.target.checked)}/> Usar acréscimo nas vendas fiadas</label><label>Percentual<input type="number" min="0" max="100" step="0.1" value={creditFeePercent} onChange={e=>setCreditFeePercent(Number(e.target.value)||0)}/></label></section><section className="card danger-card"><h2>Dados de demonstração</h2><p>O protótipo guarda os dados neste navegador. Para operação real em vários celulares, o próximo passo é conectar um banco online.</p><button className="secondary" onClick={onReset}>Restaurar demonstração</button></section></div>}
function PublicStore({business,products,delivery,payment,orders,setOrders}:{business:'lapas'|'mercadinho';products:Product[];delivery:DeliveryConfig;payment:PaymentConfig;orders:Order[];setOrders:React.Dispatch<React.SetStateAction<Order[]>>}){
const params=new URLSearchParams(window.location.search),trackingId=Number(params.get('pedido')||0);
const [cart,setCart]=useState<Record<number,number>>({}),[cartCustomizations,setCartCustomizations]=useState<Record<number,{removed:string[];additions:{name:string;price:number}[]}>>({}),[view,setView]=useState<'loja'|'pesquisa'|'pedidos'|'checkout'>('loja'),[payMethod,setPayMethod]=useState<'PIX'|'Cartão'>('PIX');
const [region,setRegion]=useState(delivery.regions[0]?.name||''),[deliveryMode,setDeliveryMode]=useState<'entrega'|'retirada'>('entrega');
const [name,setName]=useState(''),[phone,setPhone]=useState(''),[address,setAddress]=useState(''),[reference,setReference]=useState('');
const [friesOpen,setFriesOpen]=useState(false),[category,setCategory]=useState(''),[searchTerm,setSearchTerm]=useState(''),[detailProduct,setDetailProduct]=useState<Product|null>(null);
const [removedIngredients,setRemovedIngredients]=useState<string[]>([]),[chosenAdditions,setChosenAdditions]=useState<{name:string;price:number}[]>([]),[detailNote,setDetailNote]=useState(''),[crossSellIds,setCrossSellIds]=useState<number[]>([]);
const [recentOrderIds,setRecentOrderIds]=useState<number[]>(()=>load<number[]>('mn-public-orders-'+business,[]));
const allOrderProducts=products.filter(p=>p.business===business&&p.active&&p.stock>0);
const items=allOrderProducts.filter(p=>!p.name.startsWith('Batata Frita —'));
const friesOptions=products.filter(p=>p.business==='lapas'&&p.name.startsWith('Batata Frita —')).sort((a,b)=>a.id-b.id);
const selected=allOrderProducts.filter(p=>cart[p.id]);
const menuCategories=business==='lapas'?['Lanches','Porções','Pastéis','Bebidas','Doces','Sorvetes','Açaí']:Array.from(new Set(items.map(p=>p.category||'Outros'))).filter(Boolean);
const categories=Array.from(new Set([...menuCategories,...items.map(p=>p.category||'Outros')])).filter(Boolean);
const filteredItems=items.filter(p=>(!category||p.category===category)&&(!searchTerm||(p.name+' '+p.category+' '+(p.description||'')).toLowerCase().includes(searchTerm.toLowerCase())));
const itemExtra=(p:Product)=>cartCustomizations[p.id]?.additions?.reduce((s,a)=>s+a.price,0)||0;
const subtotal=selected.reduce((s,p)=>s+(p.price+itemExtra(p))*(cart[p.id]||0),0),regionFee=delivery.regions.find(r=>r.name===region)?.fee??delivery.defaultFee;
const free=delivery.freeEnabled&&subtotal>=delivery.freeAbove,fee=deliveryMode==='retirada'||free||!delivery.enabled?0:regionFee,total=subtotal+fee;
const tracked=orders.find(o=>o.id===trackingId&&o.business===business);
const customerOrders=orders.filter(o=>o.business===business&&recentOrderIds.includes(o.id));
useEffect(()=>{save('mn-public-orders-'+business,recentOrderIds)},[business,recentOrderIds]);
useEffect(()=>{if(!trackingId)return;const t=window.setInterval(()=>setOrders(v=>[...v]),1500);return()=>window.clearInterval(t)},[trackingId,setOrders]);

const clearTracking=()=>{window.history.replaceState({},'',window.location.pathname+'?loja='+business)};
const openStore=()=>{clearTracking();setView('loja');setCategory('');setSearchTerm('')};
const openSearch=()=>{clearTracking();setView('pesquisa')};
const openOrders=()=>{setView('pedidos')};
const openCategory=(c:string)=>{setCategory(c);setSearchTerm('');setView('loja')};
const add=(id:number)=>setCart(v=>({...v,[id]:Math.min((v[id]||0)+1,items.find(p=>p.id===id)?.stock||1)}));
const remove=(id:number)=>setCart(v=>{const n={...v};if((n[id]||0)<=1)delete n[id];else n[id]--;return n});
const finish=()=>{
if(!name.trim()||!phone.trim()||(deliveryMode==='entrega'&&!address.trim()))return alert('Preencha nome, celular e os dados da entrega.');
if(!selected.length)return alert('Escolha pelo menos um produto.');
if(subtotal<delivery.minOrder)return alert('O pedido mínimo é '+money(delivery.minOrder)+'.');
const order:Order={id:Date.now(),business,items:selected.map(p=>({productId:p.id,name:p.name,quantity:cart[p.id],unitPrice:p.price,removed:cartCustomizations[p.id]?.removed,additions:cartCustomizations[p.id]?.additions,note:cartCustomizations[p.id]?.note})),subtotal,fee,total,payment:payMethod,customer:{name:name.trim(),phone:phone.trim(),address:address.trim(),reference:reference.trim()},delivery:deliveryMode,region,status:'aguardando_pagamento',createdAt:new Date().toISOString()};
setOrders(v=>[order,...v]);
setRecentOrderIds(v=>[order.id,...v.filter(id=>id!==order.id)].slice(0,10));
window.history.replaceState({},'',window.location.pathname+'?loja='+business+'&pedido='+order.id);
setView('pedidos');
alert('Pedido criado! Agora faça o pagamento. O pedido só será liberado para preparo após a confirmação do pagamento.');
};

const assetRoot=window.location.pathname.startsWith('/capacitamixthais-beep')?'/capacitamixthais-beep':'';
const photoUrls:Record<string,string>={
'X-Burger':'https://images.pexels.com/photos/35731449/pexels-photo-35731449.jpeg?cs=srgb&dl=pexels-aperture-35731449.jpg&fm=jpg',
'X-Salada':'https://images.pexels.com/photos/3915915/pexels-photo-3915915.jpeg?cs=srgb&dl=pexels-horizon-content-2100060-3915915.jpg&fm=jpg',
'X-Bacon':'https://images.pexels.com/photos/19247571/pexels-photo-19247571.jpeg?cs=srgb&dl=pexels-jonathanborba-19247571.jpg&fm=jpg',
'X-Tudo':'https://images.pexels.com/photos/2874989/pexels-photo-2874989.jpeg?cs=srgb&dl=pexels-tioroshi-2874989.jpg&fm=jpg',
'Batata Frita':'https://images.pexels.com/photos/8165289/pexels-photo-8165289.jpeg?cs=srgb&dl=pexels-mart-production-8165289.jpg&fm=jpg',
'Refrigerante Lata':'https://images.pexels.com/photos/844875/pexels-photo-844875.jpeg?cs=srgb&dl=pexels-atomlaborblog-844875.jpg&fm=jpg'
};
const bannerUrl=photoUrls['X-Bacon'];
const photoClass=(p:Product)=>business==='lapas'&&photoUrls[p.name]?'store-product-img photo':p.image?'store-product-img custom-photo':'store-product-img';
const productImageStyle=(p:Product)=>{const url=photoUrls[p.name]||(p.image?assetRoot+p.image:'');return url?{backgroundImage:'url('+url+')'}:{}};
const addOrChoose=(p:Product)=>p.name==='Batata Frita'?setFriesOpen(true):add(p.id);
const openProduct=(p:Product)=>{if(p.name==='Batata Frita'){setFriesOpen(true);return}setRemovedIngredients([]);setChosenAdditions([]);setDetailProduct(p)};
const baseIngredients=(p:Product)=>{const listed=p.description?.split(',').map(x=>x.trim()).filter(x=>x.length>1)||[];if(p.category==='Lanches'){const extras=['cebola','molho especial','salada'];for(const x of extras)if(!listed.some(v=>v.toLowerCase()===x))listed.push(x)}return listed.slice(0,15)};
const additionOptions=(p:Product)=>p.category==='Lanches'?[{name:'Bacon',price:5},{name:'Queijo',price:3},{name:'Ovo',price:2},{name:'Presunto',price:3},{name:'Molho especial',price:2}]:p.category==='Porções'?[{name:'Cheddar',price:4},{name:'Catupiry',price:5},{name:'Bacon',price:5}]:p.category==='Açaí'?[{name:'Leite condensado',price:3},{name:'Leite em pó',price:3},{name:'Granola',price:3},{name:'Morango',price:4}]:p.category==='Sorvetes'?[{name:'Calda de chocolate',price:2},{name:'Calda de morango',price:2},{name:'Granulado',price:2}]:p.category==='Doces'?[{name:'Calda de chocolate',price:2},{name:'Sorvete',price:4}]:[];
const customizationExtra=chosenAdditions.reduce((s,a)=>s+a.price,0);
const crossSellProducts=(kind:'Bebidas'|'Doces'|'Sorvetes'|'Açaí')=>items.filter(p=>p.category===kind&&p.id!==detailProduct?.id).slice(0,4); const sweetPastels=items.filter(p=>p.category==='Pastéis'&&/doce|chocolate|banana/i.test(p.name)).slice(0,4);
const addCustomized=()=>{
 if(!detailProduct)return;
 if(chosenAdditions.length||removedIngredients.length||detailNote.trim()){
   setCartCustomizations(v=>({...v,[detailProduct.id]:{removed:removedIngredients,additions:chosenAdditions,note:detailNote.trim()}}))
 }
 add(detailProduct.id);
 crossSellIds.forEach(id=>add(id));
 setDetailProduct(null);setRemovedIngredients([]);setChosenAdditions([]);setDetailNote('');setCrossSellIds([]);
};

if(tracked){
return <div className="store-app">
<header className="store-head"><div className="store-brand"><img className="store-logo" src={business==='lapas'?'./logos/lapas-burguer.svg':'./logos/mercadinho-da-familia.svg'} alt="Logo"/><div><strong>{business==='lapas'?'LAPAS BURGUER':'MERCADINHO DA FAMÍLIA'}</strong><small>Pedido #{tracked.id}</small></div></div><button className="cart-button" onClick={()=>setView('checkout')}>🛒 Carrinho <b>{selected.reduce((s,p)=>s+cart[p.id],0)}</b></button></header>
<main className="tracking-screen"><div className="tracking-card"><div className="tracking-logo"><img src={business==='lapas'?'./logos/lapas-burguer.svg':'./logos/mercadinho-da-familia.svg'} alt="Logo"/></div><span className="eyebrow">ACOMPANHAMENTO</span><h1>{tracked.status==='pago_preparo'?'👨‍🍳 Seu pedido está em preparo':tracked.status==='saiu_entrega'?'🛵 Seu pedido saiu para entrega!':tracked.status==='pronto_retirada'?'🟢 Seu pedido está pronto!':tracked.status==='entregue'?'✅ Pedido entregue':'🟡 Aguardando pagamento'}</h1>
<div className="order-progress"><div className={tracked.status==='aguardando_pagamento'?'active':''}>Pagamento</div><div className={tracked.status==='pago_preparo'?'active':''}>Preparo</div><div className={(tracked.status==='saiu_entrega'||tracked.status==='pronto_retirada'||tracked.status==='entregue')?'active':''}>{tracked.delivery==='entrega'?'Entrega':'Retirada'}</div><div className={tracked.status==='entregue'?'active':''}>Concluído</div></div>
{tracked.status==='pago_preparo'&&<p>Seu pedido já foi recebido e está sendo preparado.</p>}{tracked.status==='saiu_entrega'&&<p>A Lapas Burguer agradece a preferência.<br/><strong>Bom apetite!!! ❤️🍔</strong></p>}{tracked.status==='pronto_retirada'&&<p>Já pode retirar no local.<br/>A Lapas Burguer agradece a preferência.<br/><strong>Bom apetite!!! ❤️🍔</strong></p>}{tracked.status==='aguardando_pagamento'&&<p>Finalize o pagamento. Assim que o pagamento for confirmado, seu pedido entra em preparo.</p>}
<div className="info-note"><strong>Total: {money(tracked.total)}</strong><br/>Pedido #{tracked.id}</div>
<button className="primary full" onClick={()=>setView('pedidos')}>← Voltar para meus pedidos</button></div></main>
<nav className="store-bottom-nav"><button onClick={openStore}>▣<span>Loja</span></button><button onClick={openSearch}>⌕<span>Pesquisa</span></button><button className="active" onClick={openOrders}>▤<span>Pedidos</span></button></nav>
</div>
}

return <div className="store-app">
<header className="store-head"><div className="store-brand"><img className="store-logo" src={business==='lapas'?'./logos/lapas-burguer.svg':'./logos/mercadinho-da-familia.svg'} alt="Logo"/><div><strong>{business==='lapas'?'LAPAS BURGUER':'MERCADINHO DA FAMÍLIA'}</strong><small>{business==='lapas'?'Faça seu pedido':'Compre o que precisa'}</small></div></div><button className="cart-button" onClick={()=>setView('checkout')}>🛒 Carrinho <b>{selected.reduce((s,p)=>s+cart[p.id],0)}</b></button></header>
{business==='lapas'&&<div className="store-banner"><img className="store-banner-photo" src={bannerUrl} alt="Lapas Burguer"/><img className="store-banner-logo" src="./logos/lapas-burguer.svg" alt="Logo Lapas Burguer"/></div>}
{view==='loja'&&<main className="store-public-main">
<section className="store-hero"><div><span className="eyebrow">{business==='lapas'?'LAPAS BURGUER':'MERCADINHO DA FAMÍLIA'}</span><h1>{business==='lapas'?'Seu lanche do seu jeito.':'Tudo que você precisa, pertinho de você.'}</h1><p>{business==='lapas'?'Escolha, monte seu pedido e acompanhe tudo por aqui.':'Escolha os produtos, monte seu pedido e acompanhe tudo por aqui.'}</p></div></section>
<div className="store-search"><span>⌕</span><input value={searchTerm} onChange={e=>setSearchTerm(e.target.value)} placeholder="Pesquisar produtos..."/><button onClick={()=>setView('pesquisa')}>Categorias</button></div>
{category&&<div className="selected-category">Categoria: <strong>{category}</strong><button onClick={()=>setCategory('')}>×</button></div>}
<section className="store-grid">{filteredItems.map(p=><article className="store-product" key={p.id} onClick={()=>openProduct(p)}><div className={photoClass(p)} style={productImageStyle(p)}>{business==='lapas'?'🍔':'🛒'}</div><div><strong>{p.name}</strong>{p.description&&<p className="store-description">{p.description}</p>}<small>{p.category}</small><b>{money(p.price)}</b></div><button onClick={e=>{e.stopPropagation();addOrChoose(p)}}>{p.name==='Batata Frita'?'🍟 Escolha sua batata':'+ Adicionar'}</button></article>)}</section>
{!filteredItems.length&&<div className="empty">Nenhum produto encontrado.</div>}{detailProduct&&<div className="store-modal-backdrop product-detail-backdrop" onClick={()=>setDetailProduct(null)}><div className="store-modal product-detail-modal" onClick={e=>e.stopPropagation()}><button className="store-modal-close" onClick={()=>setDetailProduct(null)}>✕</button><div className={photoClass(detailProduct)+' product-detail-photo'} style={productImageStyle(detailProduct)}>{business==='lapas'?'🍔':'🛒'}</div><div className="product-detail-content"><span className="eyebrow">{detailProduct.category}</span><h2>{detailProduct.name}</h2><div className="product-detail-price">{money(detailProduct.price+customizationExtra)}</div><div className="product-detail-description"><strong>O que vem:</strong><p>{detailProduct.description||'Descrição deste produto ainda não cadastrada.'}</p></div>{baseIngredients(detailProduct).length>0&&<section className="custom-section"><h3>🚫 Quer tirar algum ingrediente?</h3><p className="custom-help">Marque o que você não quer no seu lanche.</p><div className="custom-options">{baseIngredients(detailProduct).map(ing=><label key={ing} className="custom-option"><input type="checkbox" checked={removedIngredients.includes(ing)} onChange={e=>setRemovedIngredients(v=>e.target.checked?[...v,ing]:v.filter(x=>x!==ing))}/><span>Sem {ing}</span></label>)}</div></section>}{additionOptions(detailProduct).length>0&&<section className="custom-section"><h3>➕ Quer acrescentar?</h3><p className="custom-help">Escolha os adicionais que quiser.</p><div className="custom-options">{additionOptions(detailProduct).map(a=><label key={a.name} className="custom-option"><input type="checkbox" checked={chosenAdditions.some(x=>x.name===a.name)} onChange={e=>setChosenAdditions(v=>e.target.checked?[...v,a]:v.filter(x=>x.name!==a.name))}/><span>{a.name}</span><b>+ {money(a.price)}</b></label>)}</div></section>}{business==='lapas'&&<section className="custom-section cross-sell-section"><h3>🥤 Vai comer com bebida?</h3><p className="custom-help">Aproveite e escolha uma bebida para acompanhar.</p><div className="cross-sell-list">{crossSellProducts('Bebidas').map(p=><label key={p.id} className="cross-sell-option"><input type="checkbox" checked={crossSellIds.includes(p.id)} onChange={e=>setCrossSellIds(v=>e.target.checked?[...v,p.id]:v.filter(x=>x!==p.id))}/><span>{p.name}</span><b>+ {money(p.price)}</b></label>)}</div></section>}
{business==='lapas'&&<section className="custom-section cross-sell-section"><h3>🍰 Quer uma sobremesa?</h3><p className="custom-help">Doces, sorvetes e açaí podem completar seu pedido.</p><div className="cross-sell-list">{[...crossSellProducts('Doces'),...crossSellProducts('Sorvetes'),...crossSellProducts('Açaí'),...sweetPastels].slice(0,8).map(p=><label key={p.id} className="cross-sell-option"><input type="checkbox" checked={crossSellIds.includes(p.id)} onChange={e=>setCrossSellIds(v=>e.target.checked?[...v,p.id]:v.filter(x=>x!==p.id))}/><span>{p.name}</span><b>+ {money(p.price)}</b></label>)}</div></section>}
<section className="custom-section"><h3>📝 Alguma observação?</h3><p className="custom-help">Escreva como quer o seu pedido ou o que não quer no preparo.</p><textarea className="product-observation" value={detailNote} onChange={e=>setDetailNote(e.target.value)} placeholder="Ex.: pouco molho, bem passado, sem ketchup, cortar ao meio..." rows={4}/></section>
{(removedIngredients.length>0||chosenAdditions.length>0||detailNote.trim())&&<div className="custom-summary">{removedIngredients.length>0&&<div>Sem: {removedIngredients.join(', ')}</div>}{chosenAdditions.length>0&&<div>Adicionais: {chosenAdditions.map(a=>a.name).join(', ')}</div>}{detailNote.trim()&&<div>Obs.: {detailNote.trim()}</div>}</div>}<div className="product-detail-note">Os adicionais alteram o valor do item. Os ingredientes retirados não geram desconto.</div><button className="primary full" disabled={detailProduct.stock<=0||detailProduct.price<=0} onClick={addCustomized}>{detailProduct.stock>0&&detailProduct.price>0?'＋ Adicionar ao pedido':'Indisponível'}</button></div></div></div>}{friesOpen&&<div className="store-modal-backdrop" onClick={()=>setFriesOpen(false)}><div className="store-modal" onClick={e=>e.stopPropagation()}><button className="store-modal-close" onClick={()=>setFriesOpen(false)}>✕</button><div className="store-product-img photo fries-modal-photo" style={productImageStyle({name:'Batata Frita'} as Product)}></div><h2>🍟 Escolha sua batata</h2><p>Selecione o tamanho da porção.</p><div className="fries-options">{friesOptions.map(p=><div className="fries-option" key={p.id}><div><strong>{p.name.replace('Batata Frita — ','')}</strong><small>{p.description||'Porção de batata frita.'}</small></div><div className="fries-option-action"><b>{p.price>0?money(p.price):'Preço a definir'}</b><button className="primary" disabled={p.price<=0||p.stock<=0} onClick={()=>{add(p.id);setFriesOpen(false)}}>{p.price>0&&p.stock>0?'Adicionar':'Indisponível'}</button></div></div>)}</div></div></div>}
</main>}
{view==='pesquisa'&&<main className="store-public-main"><section className="store-hero compact"><div><span className="eyebrow">PESQUISA</span><h1>Encontre o que você quer.</h1><p>Escolha uma categoria para ver os produtos.</p></div></section><div className="category-list">{categories.map(c=><button key={c} onClick={()=>openCategory(c)}>{c}<span>›</span></button>)}</div></main>}
{view==='pedidos'&&<main className="store-public-main"><section className="store-hero compact"><div><span className="eyebrow">MEUS PEDIDOS</span><h1>Acompanhe seus pedidos.</h1><p>Veja o andamento dos pedidos feitos neste aparelho.</p></div></section>{customerOrders.length?<div className="public-orders">{customerOrders.map(o=><article className="public-order-card" key={o.id}><div className="card-head"><div><strong>Pedido #{o.id}</strong><small>{dateBR(o.createdAt)}</small></div><b>{money(o.total)}</b></div><div className="public-order-status">{o.status==='aguardando_pagamento'?'🟡 Aguardando pagamento':o.status==='pago_preparo'?'👨‍🍳 Em preparo':o.status==='saiu_entrega'?'🛵 Saiu para entrega':o.status==='pronto_retirada'?'🟢 Pronto para retirada':'✅ Entregue'}</div><div className="public-order-items">{o.items.map(i=><span key={i.productId}>{i.quantity}× {i.name}</span>)}</div><button className="secondary full" onClick={()=>{window.history.replaceState({},'',window.location.pathname+'?loja='+business+'&pedido='+o.id);window.location.reload()}}>Acompanhar este pedido</button></article>)}</div>:<div className="public-empty-orders"><div>▤</div><h2>Sem pedidos no momento...</h2><p>Assim que fizer algum pedido ele aparecerá aqui. :)</p></div>}</main>}
{view==='checkout'&&<main className="checkout public-checkout"><button className="back-store" onClick={()=>setView('loja')}>← Voltar à loja</button><h1>Seu carrinho</h1>{selected.map(p=><div className="cart-row" key={p.id}><div><strong>{p.name}</strong><small>{p.description||money(p.price)+' cada'}</small>{cartCustomizations[p.id]?.removed?.length>0&&<small className="cart-custom">Sem: {cartCustomizations[p.id].removed.join(', ')}</small>}{cartCustomizations[p.id]?.additions?.length>0&&<small className="cart-custom">+ {cartCustomizations[p.id].additions.map(a=>a.name).join(', ')}</small>}{cartCustomizations[p.id]?.note&&<small className="cart-custom">📝 {cartCustomizations[p.id].note}</small>}</div><div><button onClick={()=>remove(p.id)}>−</button><b>{cart[p.id]}</b><button onClick={()=>add(p.id)}>+</button></div><strong>{money((p.price+itemExtra(p))*cart[p.id])}</strong></div>)}<div className="checkout-card"><div className="form-grid"><label>Entrega ou retirada<select value={deliveryMode} onChange={e=>setDeliveryMode(e.target.value as 'entrega'|'retirada')}><option value="entrega">🛵 Entrega</option><option value="retirada">🟢 Retirada no local</option></select></label>{deliveryMode==='entrega'&&<label>Região<select value={region} onChange={e=>setRegion(e.target.value)}>{delivery.regions.map(r=><option key={r.name}>{r.name}</option>)}</select></label>}</div><div className="checkout-line"><span>Subtotal</span><b>{money(subtotal)}</b></div><div className="checkout-line"><span>Frete</span><b>{fee?'+'+money(fee):'GRÁTIS'}</b></div><div className="checkout-line total"><span>Total</span><b>{money(total)}</b></div><div className="form-grid"><label>Nome<input value={name} onChange={e=>setName(e.target.value)}/></label><label>Celular<input value={phone} onChange={e=>setPhone(e.target.value)}/></label><label>Endereço<input value={address} onChange={e=>setAddress(e.target.value)} placeholder={deliveryMode==='retirada'?'Não é necessário':''}/></label><label>Referência<input value={reference} onChange={e=>setReference(e.target.value)}/></label></div><h3>Forma de pagamento</h3><div className="payment-choice"><button className={payMethod==='PIX'?'primary':'secondary'} onClick={()=>setPayMethod('PIX')}>🟢 PIX</button><button className={payMethod==='Cartão'?'primary':'secondary'} onClick={()=>setPayMethod('Cartão')}>💳 Cartão</button></div>{payMethod==='PIX'&&<div className="info-note">🟢 PIX: <strong>{payment.pixKey}</strong><br/><button className="secondary" style={{marginTop:8}} onClick={()=>navigator.clipboard?.writeText(payment.pixKey)}>📋 Copiar chave Pix</button><br/><small>Após o pagamento, o pedido ficará aguardando a confirmação.</small></div>}{payMethod==='Cartão'&&payment.cardLink&&<button className="secondary full" onClick={()=>window.open(payment.cardLink,'_blank')}>💳 Pagar pelo link PagBank</button>}<button className="primary full" disabled={!selected.length} onClick={finish}>✓ Criar pedido e continuar</button></div></main>}
<nav className="store-bottom-nav"><button className={view==='loja'?'active':''} onClick={openStore}>▣<span>Loja</span></button><button className={view==='pesquisa'?'active':''} onClick={()=>setView('pesquisa')}>⌕<span>Pesquisa</span></button><button className={view==='pedidos'?'active':''} onClick={()=>setView('pedidos')}>▤<span>Pedidos</span>{customerOrders.length>0&&<b>{customerOrders.length}</b>}</button></nav>
</div>
}

function OrdersPage({orders,setOrders}:{orders:Order[];setOrders:React.Dispatch<React.SetStateAction<Order[]>>}){const [filter,setFilter]=useState<'all'|'lapas'|'mercadinho'>('all');const list=orders.filter(o=>filter==='all'||o.business===filter);const setStatus=(id:number,status:OrderStatus)=>setOrders(v=>v.map(o=>o.id===id?{...o,status}:o));return <div><div className="page-head"><div><span className="eyebrow">PEDIDOS ONLINE</span><h1>Pedidos</h1><p>Pagamento confirmado libera o pedido para preparo. Depois, avance apenas quando realmente estiver pronto para sair ou ser retirado.</p></div><select value={filter} onChange={e=>setFilter(e.target.value as any)}><option value="all">Todos</option><option value="lapas">🍔 Lapas Burguer</option><option value="mercadinho">🛒 Mercadinho da Família</option></select></div><div className="grid-2">{list.map(o=><section className="card" key={o.id}><div className="card-head"><div><h2>#{o.id} · {o.business==='lapas'?'🍔 LAPAS BURGUER':'🛒 MERCADINHO DA FAMÍLIA'}</h2><p>{o.customer.name} · {o.customer.phone}</p></div><strong>{money(o.total)}</strong></div><div className="alert-list">{o.items.map(i=><div key={i.productId}><div><span>{i.quantity} × {i.name}</span>{i.removed?.length? <small className="order-detail-line">🚫 Sem: {i.removed.join(', ')}</small>:null}{i.additions?.length? <small className="order-detail-line">➕ Adicionais: {i.additions.map(a=>a.name).join(', ')}</small>:null}{i.note?<small className="order-detail-line">📝 Observação: {i.note}</small>:null}</div><b>{money(i.quantity*(i.unitPrice+(i.additions?.reduce((s,a)=>s+a.price,0)||0)))}</b></div>)}</div><div className="info-note">{o.delivery==='entrega'?'🛵 Entrega: '+o.customer.address:'🟢 Retirada no local'}{o.customer.reference&&<><br/>Ref.: {o.customer.reference}</>}<br/><strong>Status: {o.status==='aguardando_pagamento'?'🟡 Aguardando pagamento':o.status==='pago_preparo'?'👨‍🍳 EM PREPARO':o.status==='saiu_entrega'?'🛵 SAIU PARA ENTREGA':o.status==='pronto_retirada'?'🟢 PRONTO PARA RETIRADA':'✅ ENTREGUE'}</strong></div><div className="head-buttons">{o.status==='aguardando_pagamento'&&<button className="primary" onClick={()=>setStatus(o.id,'pago_preparo')}>🟢 Confirmar pagamento e iniciar preparo</button>}{o.status==='pago_preparo'&&o.delivery==='entrega'&&<button className="primary" onClick={()=>setStatus(o.id,'saiu_entrega')}>🛵 Saiu para entrega</button>}{o.status==='pago_preparo'&&o.delivery==='retirada'&&<button className="primary" onClick={()=>setStatus(o.id,'pronto_retirada')}>🟢 Pronto para retirada</button>}{(o.status==='saiu_entrega'||o.status==='pronto_retirada')&&<button className="secondary" onClick={()=>setStatus(o.id,'entregue')}>✓ Encerrar pedido</button>}</div></section>)}</div>{!list.length&&<div className="empty">Nenhum pedido online.</div>}</div>}
function SorteiosPage({customers,products}:{customers:Customer[];products:Product[]}){
const [events,setEvents]=useState(()=>load('mn-raffle-events',[
{id:1,name:'Páscoa',dateSuggestion:'Domingo de Páscoa',active:true,prize:'Definir prêmio',note:'Sugestão: realizar no domingo de Páscoa.'},
{id:2,name:'Dia das Mães',dateSuggestion:'Domingo do Dia das Mães',active:true,prize:'Definir prêmio',note:'Sugestão: realizar no sábado anterior ou no próprio domingo.'},
{id:3,name:'Dia dos Namorados',dateSuggestion:'12 de junho',active:false,prize:'Definir prêmio',note:'Sugestão: realizar no dia 12/06 ou no sábado mais próximo.'},
{id:4,name:'Dia dos Pais',dateSuggestion:'Domingo do Dia dos Pais',active:false,prize:'Definir prêmio',note:'Sugestão: realizar no sábado anterior ou no próprio domingo.'},
{id:5,name:'Dia das Crianças',dateSuggestion:'12 de outubro',active:true,prize:'Definir prêmio',note:'Sugestão: realizar no dia 12/10.'},
{id:6,name:'Black Friday',dateSuggestion:'Última sexta-feira de novembro',active:false,prize:'Definir prêmio',note:'Sugestão: combinar com campanha de compras.'},
{id:7,name:'Natal',dateSuggestion:'20 a 23 de dezembro',active:true,prize:'Definir prêmio',note:'Sugestão: sortear alguns dias antes do Natal para facilitar a entrega.'},
{id:8,name:'Ano Novo',dateSuggestion:'28 a 30 de dezembro',active:false,prize:'Definir prêmio',note:'Sugestão: realizar antes da virada.'}
]));
const [winner,setWinner]=useState<string|null>(null);
const [eventId,setEventId]=useState<number>(1);
const [newEvent,setNewEvent]=useState('');
const saveEvents=(next:any[])=>{setEvents(next);save('mn-raffle-events',next)};
const draw=()=>{const eligible=customers.filter(c=>c.name.trim());if(!eligible.length){setWinner('Cadastre clientes antes de realizar um sorteio.');return;}const w=eligible[Math.floor(Math.random()*eligible.length)];setWinner(w.name)};
const activeEvents=events.filter((e:any)=>e.active);
const selected=events.find((e:any)=>e.id===eventId);
return <div><div className="page-head"><div><span className="eyebrow">RELACIONAMENTO</span><h1>🎁 Sorteios</h1><p>Planeje datas, ative ou desative campanhas e faça o sorteio entre os clientes cadastrados.</p></div></div>
<section className="card"><div className="card-head"><div><h2>Datas importantes</h2><p>As sugestões são apenas um calendário inicial. A Thaís decide quais campanhas realmente quer usar.</p></div></div>
<div className="event-grid">{events.map((e:any)=><div className="event-card" key={e.id}><div className="event-top"><strong>{e.name}</strong><label className="switch"><input type="checkbox" checked={e.active} onChange={()=>saveEvents(events.map((x:any)=>x.id===e.id?{...x,active:!x.active}:x))}/><span></span></label></div><div>{e.dateSuggestion}</div><small>{e.note}</small><input value={e.prize} onChange={ev=>saveEvents(events.map((x:any)=>x.id===e.id?{...x,prize:ev.target.value}:x))} placeholder="Prêmio sugerido/definido"/></div>)}</div>
<div className="inline-form"><input value={newEvent} onChange={e=>setNewEvent(e.target.value)} placeholder="Nova data ou campanha"/><button className="secondary" onClick={()=>{if(!newEvent.trim())return;const id=Date.now();saveEvents([...events,{id,name:newEvent,dateSuggestion:'Definir data',active:false,prize:'Definir prêmio',note:'Cadastre a data desejada.'}]);setNewEvent('')}}>+ Adicionar data</button></div></section>
<section className="card"><div className="card-head"><div><h2>🎟️ Realizar sorteio</h2><p>Somente clientes cadastrados entram no sorteio.</p></div></div><div className="form-grid"><label>Campanha<select value={eventId} onChange={e=>setEventId(Number(e.target.value))}>{activeEvents.map((e:any)=><option key={e.id} value={e.id}>{e.name}</option>)}</select></label><label>Prêmio<input value={selected?.prize||''} readOnly/></label></div><button className="primary" onClick={draw}>🎉 Sortear cliente</button>{winner&&<div className="winner">🏆 {winner}</div>}</section>
<section className="card"><div className="card-head"><div><h2>💡 Sugestão de prêmio</h2><p>O sistema sugere somente produtos que já estão cadastrados no Mercadinho.</p></div></div><div className="chips">{products.filter(p=>p.business==='mercadinho'&&p.active&&p.price>0).slice(0,8).map(p=><span className="chip" key={p.id}>{p.name}</span>)}</div></section>\n<section className="card message-section"><div className="card-head"><div><span className="eyebrow">MENSAGENS PRONTAS</span><h2>💌 Datas especiais</h2><p>Mensagens já preparadas para o Mercadinho da Família. É só escolher a data e copiar para o WhatsApp.</p></div></div><div className="message-grid">{messageTemplates.map(([date,title,text])=><article className="message-card" key={date}><div className="message-ribbon">{date}</div><h3>{title}</h3><div className="message-text">{text}</div><button className="primary full" onClick={()=>navigator.clipboard?.writeText(text).then(()=>alert('Mensagem copiada!'))}>📋 Copiar mensagem</button></article>)}</div></section>
</div>}
const messageTemplates=[
['Páscoa','🐰🌷 Feliz Páscoa!','O Mercadinho da Família deseja a todos os nossos clientes uma Feliz Páscoa! 💛\n\nAproveitamos esta data especial para agradecer de coração pela confiança, pelo carinho e por fazerem parte da nossa história.\n\nE para agradecer essa parceria, estamos preparando um pequeno mimo para vocês, que fazem tudo valer a pena! 🎁\n\nCom carinho,\nThaís, Bruno e Heitor 💚'],
['Dia das Mães','💐 Feliz Dia das Mães!','O Mercadinho da Família deseja a todas as mães um Feliz Dia das Mães, cheio de amor, carinho e momentos especiais! 💐💗\n\nAproveitamos para agradecer a cada cliente pela confiança e pela parceria de sempre.\n\nPreparamos um pequeno mimo para vocês, como forma de agradecer por fazerem parte da nossa caminhada. 🎁\n\nCom carinho,\nThaís, Bruno e Heitor 💚'],
['Dia dos Namorados','❤️ Feliz Dia dos Namorados!','O Mercadinho da Família deseja a todos um Feliz Dia dos Namorados, repleto de carinho, amor e bons momentos! ❤️\n\nMuito obrigado por escolherem estar conosco e por fazerem parte da nossa história.\n\nPara celebrar essa parceria, estamos preparando um pequeno mimo para vocês! 🎁\n\nCom carinho,\nThaís, Bruno e Heitor 💚'],
['Dia dos Pais','👔 Feliz Dia dos Pais!','O Mercadinho da Família deseja a todos os pais um Feliz Dia dos Pais, com muito carinho, saúde e momentos felizes em família! 💙\n\nObrigado a todos os nossos clientes pela confiança e pela parceria. Vocês fazem tudo valer a pena!\n\nPreparamos um pequeno mimo para agradecer esse carinho. 🎁\n\nCom carinho,\nThaís, Bruno e Heitor 💚'],
['Dia das Crianças','🎈 Feliz Dia das Crianças!','O Mercadinho da Família deseja a todas as crianças um Feliz Dia das Crianças, cheio de alegria, brincadeiras e sorrisos! 🎈💛\n\nAgradecemos a cada cliente que caminha conosco e fortalece o nosso pequeno negócio todos os dias.\n\nTemos um pequeno mimo preparado para vocês! 🎁\n\nCom carinho,\nThaís, Bruno e Heitor 💚'],
['Black Friday','🛍️ Black Friday no Mercadinho da Família!','A Black Friday chegou! 🛍️✨\n\nAproveitamos esta oportunidade para agradecer a confiança e a parceria de todos os nossos clientes.\n\nE, como forma de retribuir esse carinho, estamos preparando um pequeno mimo para vocês! 🎁\n\nFiquem de olho nas novidades do Mercadinho da Família.\n\nCom carinho,\nThaís, Bruno e Heitor 💚'],
['Natal','🎄 Feliz Natal!','O Mercadinho da Família deseja a todos os nossos clientes um Feliz Natal, cheio de paz, amor, saúde e momentos especiais ao lado de quem vocês amam! 🎄❤️\n\nNosso muito obrigado por toda confiança, carinho e parceria durante o ano.\n\nVocês fazem tudo valer a pena. Por isso, preparamos um pequeno mimo para agradecer! 🎁\n\nCom carinho,\nThaís, Bruno e Heitor 💚'],
['Ano Novo','✨ Feliz Ano Novo!','O Mercadinho da Família deseja a todos os nossos clientes um Feliz Ano Novo, cheio de saúde, paz, prosperidade e muitas realizações! ✨🥂\n\nObrigado por fazerem parte da nossa história e por toda a parceria ao longo do ano.\n\nQue possamos continuar juntos em mais um ano. E, para agradecer esse carinho, temos um pequeno mimo para vocês! 🎁\n\nCom carinho,\nThaís, Bruno e Heitor 💚']
]

function IntelligencePage({products,sales,purchases,customers,setCustomers,requests,setRequests,places,setPlaces,setProducts}:{products:Product[];sales:Sale[];purchases:Purchase[];customers:Customer[];setCustomers:(x:Customer[])=>void;requests:{id:number;name:string;customer:string;date:string;status:'pendente'|'avaliar'|'não trabalhar'}[];setRequests:(x:any[])=>void;places:string[];setPlaces:(x:string[])=>void;setProducts:React.Dispatch<React.SetStateAction<Product[]>>}){
const [tab,setTab]=useState<'estoque'|'compras'|'clientes'|'pedidos'|'datas'>('estoque')
const now=Date.now()
const last7=sales.filter(s=>now-new Date(s.date).getTime()<=7*86400000)
const last30=sales.filter(s=>now-new Date(s.date).getTime()<=30*86400000)
const counts=last7.reduce<Record<number,number>>((a,s)=>{a[s.productId]=(a[s.productId]||0)+s.quantity;return a},{})
const counts30=last30.reduce<Record<number,number>>((a,s)=>{a[s.productId]=(a[s.productId]||0)+s.quantity;return a},{})
const suggested=(p:Product)=>Math.max(1,Math.ceil(((counts30[p.id]||0)/30)*2))
return <div>
<div className="page-head"><div><span className="eyebrow">ASSISTENTE DO NEGÓCIO</span><h1>Inteligência do Mercadinho</h1><p>O sistema analisa vendas e procura para ajudar a Thaís a decidir. Nada é comprado ou alterado automaticamente.</p></div></div>
<div className="toolbar" style={{display:'flex',gap:8,flexWrap:'wrap'}}>
{[['estoque','📦 Estoque'],['compras','🚚 Compras e preços'],['clientes','👤 Clientes'],['pedidos','📝 Pedidos'],['datas','🎁 Datas especiais']].map(([k,label])=><button key={k} className={tab===k?'primary':'secondary'} onClick={()=>setTab(k as typeof tab)}>{label}</button>)}
</div>
{tab==='estoque'&&<section className="card">
<h2>⚠️ Estoque mínimo inteligente</h2><p className="muted">O sistema usa o histórico recente para sugerir um mínimo com 2 dias de segurança. A sugestão pode ser ajustada produto a produto.</p>
<div className="table-wrap"><table><thead><tr><th>Produto</th><th>Vendidos (7 dias)</th><th>Média/dia</th><th>Estoque atual</th><th>Mínimo sugerido</th><th>Sinal</th></tr></thead><tbody>
{products.map(p=>{const sold=counts[p.id]||0,min=suggested(p);return <tr key={p.id}><td><strong>{p.name}</strong><small>{p.business==='lapas'?'Lapas Burguer':'Mercadinho'}</small></td><td>{sold}</td><td>{(sold/7).toFixed(1)}</td><td>{p.stock}</td><td><strong>{min}</strong></td><td>{p.stock<=min?<span className="status danger">Comprar</span>:<span className="status ok">Normal</span>}</td></tr>})}</tbody></table></div>
<div className="info-note">💡 O ranking semanal considera os últimos 7 dias reais. O estoque mínimo usa até 30 dias de histórico para não reagir demais a uma semana atípica.</div>
</section>}
{tab==='compras'&&<PurchaseIntelligence products={products} purchases={purchases} places={places} setPlaces={setPlaces} setProducts={setProducts}/>}
{tab==='clientes'&&<CustomerIntelligence customers={customers} setCustomers={setCustomers}/>}
{tab==='pedidos'&&<RequestIntelligence requests={requests} setRequests={setRequests}/>}
{tab==='datas'&&<SpecialIntelligence customers={customers} products={products.filter(p=>p.business==='mercadinho')}/>}
</div>
}

function PurchaseIntelligence({products,purchases,places,setPlaces,setProducts}:{products:Product[];purchases:Purchase[];places:string[];setPlaces:(x:string[])=>void;setProducts:React.Dispatch<React.SetStateAction<Product[]>>}){
const [id,setId]=useState(products[0]?.id||0),[qty,setQty]=useState(1),[place,setPlace]=useState(places[0]||''),[cost,setCost]=useState(products[0]?.cost||0),[accepted,setAccepted]=useState<number|null>(null),[newPlace,setNewPlace]=useState('')
const p=products.find(x=>x.id===id);const setProduct=(n:number)=>{setId(n);const x=products.find(p=>p.id===n);if(x)setCost(x.cost)}
const options=[cost*1.10,cost*1.15,cost*1.20].map(v=>Number(v.toFixed(2)))
const demand=products.map(p=>({p,sold:purchases.length?0:0})).slice(0,0)
return <div className="grid-2">
<section className="card"><h2>🚚 Registrar compra</h2><label>Produto<select value={id} onChange={e=>setProduct(Number(e.target.value))}>{products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>
<div className="form-grid"><label>Quantidade<input type="number" min="1" value={qty} onChange={e=>setQty(Number(e.target.value))}/></label><label>Onde comprou<select value={place} onChange={e=>setPlace(e.target.value)}>{places.map(x=><option key={x}>{x}</option>)}</select></label></div>
<label>Valor pago por unidade<input type="number" step="0.01" value={cost} onChange={e=>setCost(Number(e.target.value))}/></label>
<div className="total-box"><span>Total da compra</span><strong>{money(cost*qty)}</strong></div>
<div className="form-grid"><input placeholder="Novo local de compra" value={newPlace} onChange={e=>setNewPlace(e.target.value)}/><button className="secondary" onClick={()=>{if(newPlace.trim()){setPlaces([...places,newPlace.trim()]);setPlace(newPlace.trim());setNewPlace('')}}}>Adicionar local</button></div>
</section>
<section className="card"><h2>🏷️ Preço de venda sugerido</h2><p className="muted">Duas opções principais + uma terceira margem. Thaís escolhe, pode alterar e só depois confirma.</p>
{options.map((v,i)=><button key={v} className={accepted===v?'primary full':'secondary full'} style={{marginBottom:8,textAlign:'left'}} onClick={()=>{setAccepted(v);setProducts(list=>list.map(x=>x.id===id?{...x,price:v,cost}:x))}}><strong>{i===0?'Custo + 10%':i===1?'Custo + 15%':'Custo + 20%'}</strong> — {money(v)}</button>)}
<div className="total-box"><span>Preço aceito</span><strong>{accepted===null?'Aguardando escolha':money(accepted)}</strong></div>
<p className="muted">Preço anterior: {money(p?.price||0)} · custo atual: {money(cost)}</p>
<div className="info-note">✓ O aceite fica registrado na decisão da Thaís. Na próxima etapa, vamos persistir o histórico de preços e aplicar o valor escolhido ao cadastro do produto.</div>
</section>
</div>
}

function CustomerIntelligence({customers,setCustomers}:{customers:Customer[];setCustomers:(x:Customer[])=>void}){
const [name,setName]=useState(''),[phone,setPhone]=useState(''),[address,setAddress]=useState(''),[reference,setReference]=useState('')
const add=()=>{if(!name.trim())return;setCustomers([...customers,{id:Date.now(),name:name.trim(),phone,address,reference,balance:0}]);setName('');setPhone('');setAddress('');setReference('')}
return <section className="card"><h2>👤 Clientes, entregas e fiado</h2><p className="muted">O mesmo cadastro serve para entrega, relacionamento e futuras ações/sorteios. Fiado continua separado do simples cadastro.</p>
<div className="form-grid"><label>Nome<input value={name} onChange={e=>setName(e.target.value)}/></label><label>Celular<input value={phone} onChange={e=>setPhone(e.target.value)}/></label><label>Endereço<input value={address} onChange={e=>setAddress(e.target.value)}/></label><label>Referência<input value={reference} onChange={e=>setReference(e.target.value)}/></label></div><button className="primary" onClick={add}>+ Cadastrar cliente</button>
<div style={{marginTop:18}}>{customers.map(c=><div className="customer" key={c.id}><div><strong>{c.name}</strong><small>{c.phone||'Sem celular'} · {c.address||'Sem endereço'} · {c.reference||'Sem referência'}</small></div><b>{money(c.balance)} em aberto</b></div>)}</div></section>
}

function RequestIntelligence({requests,setRequests}:{requests:{id:number;name:string;customer:string;date:string;status:'pendente'|'avaliar'|'não trabalhar'}[];setRequests:(x:any[])=>void}){
const [name,setName]=useState(''),[customer,setCustomer]=useState('')
const add=()=>{if(!name.trim())return;setRequests([{id:Date.now(),name:name.trim(),customer,date:new Date().toISOString(),status:'pendente'},...requests]);setName('');setCustomer('')}
const change=(id:number,status:'avaliar'|'não trabalhar')=>setRequests(requests.map(r=>r.id===id?{...r,status}:r))
const grouped=Object.entries(requests.reduce<Record<string,number>>((a,r)=>{a[r.name]=(a[r.name]||0)+1;return a},{})).sort((a,b)=>b[1]-a[1])
return <section className="card"><h2>📝 O que os clientes estão pedindo?</h2><p className="muted">Registre produtos que ainda não existem no estoque. A frequência da procura ajuda a decidir se vale testar.</p><div className="form-grid"><input placeholder="Produto solicitado" value={name} onChange={e=>setName(e.target.value)}/><input placeholder="Cliente (opcional)" value={customer} onChange={e=>setCustomer(e.target.value)}/></div><button className="primary" onClick={add}>+ Registrar pedido</button>
<h3 style={{marginTop:22}}>Procura acumulada</h3>{grouped.map(([n,q])=><div className="mini-row" key={n}><span>{n}</span><strong>{q} {q===1?'pedido':'pedidos'}</strong><small>{q>=5?'Vale avaliar com atenção':q>=2?'Observar demanda':'Primeira solicitação'}</small></div>)}
<h3 style={{marginTop:22}}>Pedidos registrados</h3>{requests.map(r=><div className="mini-row" key={r.id}><span><strong>{r.name}</strong><small>{r.customer||'Cliente não informado'} · {dateBR(r.date)}</small></span><div><button className="tiny" onClick={()=>change(r.id,'avaliar')}>Avaliar</button><button className="tiny" onClick={()=>change(r.id,'não trabalhar')}>Não trabalhar</button><small>{r.status}</small></div></div>)}</section>
}

function SpecialIntelligence({customers,products}:{customers:Customer[];products:Product[]}){
const [event,setEvent]=useState(''),[winner,setWinner]=useState('')
const events=[['Páscoa','Chocolate, biscoitos e bebidas, se estiverem cadastrados'],['Dia das Mães','Café, chocolate ou itens de presente já vendidos'],['Dia das Crianças','Chocolate, biscoitos e bebidas'],['Natal','Panetone, chocolate, bebidas ou kit de produtos cadastrados']]
const suggest=event==='Natal'?products.filter(p=>/panetone|chocolate|refrigerante|biscoito/i.test(p.name)):products.filter(p=>/chocolate|biscoito|café|refrigerante/i.test(p.name))
return <section className="card"><h2>🎁 Datas especiais e sorteios</h2><p className="muted">O sistema sugere somente itens já cadastrados no Mercadinho e disponíveis como ideia de prêmio.</p><div className="form-grid"><select value={event} onChange={e=>{setEvent(e.target.value);setWinner('')}}><option value="">Escolha uma data</option>{events.map(e=><option key={e[0]} value={e[0]}>{e[0]}</option>)}</select><div className="info-note" style={{margin:0}}>{events.find(e=>e[0]===event)?.[1]||'Selecione uma data para ver a sugestão.'}</div></div>
{event&&<><h3>Sugestões disponíveis</h3>{suggest.map(p=><div className="mini-row" key={p.id}><span>{p.name}</span><strong>{money(p.price)}</strong></div>)}<button className="primary" disabled={!customers.length} onClick={()=>{if(customers.length)setWinner(customers[Math.floor(Math.random()*customers.length)].name)}}>🎉 Sortear entre clientes</button>{winner&&<div className="result-hero" style={{marginTop:15}}><div><span>Cliente sorteado</span><strong>{winner}</strong></div></div>}</>}</section>
}

export default App
